tool_input.command:
python3 - <<'EOF'
p='src/orders.js'
s=open(p).read()
s=s.replace('import { priceCart }','import { percentOf } from "./money.js";\nimport { priceCart }')
s+='''
const RESTOCKING_RATE = 0.1;

const REFUND_RULES = {
  damaged: (order) => order.total,
  late: (order) => order.shipping.cost,
  "changed-mind": (order) => order.net - percentOf(order.net, RESTOCKING_RATE),
};

/**
 * Refund in cents for an order and a reason: "damaged" refunds the total, "late" the
 * shipping cost, "changed-mind" the net amount less a 10% restocking fee. Any other reason refunds 0.
 */
export function refundFor(order, reason) {
  const rule = Object.hasOwn(REFUND_RULES, reason) ? REFUND_RULES[reason] : () => 0;
  return rule(order);
}
'''
open(p,'w').write(s)
t='test/orders.test.js'
s=open(t).read()
s=s.replace('import { placeOrder }','import { placeOrder, refundFor }')
s+='''
test("refunds follow the reason: total, shipping, net less restocking fee, or nothing", () => {
  const order = { net: 26905, shipping: { cost: 5400 }, total: 34255 };
  assert.equal(refundFor(order, "damaged"), 34255);
  assert.equal(refundFor(order, "late"), 5400);
  assert.equal(refundFor(order, "changed-mind"), 26905 - 2691);
  assert.equal(refundFor(order, "other"), 0);
  assert.equal(refundFor(order, undefined), 0);
  assert.equal(refundFor(order, "toString"), 0);
});
'''
open(t,'w').write(s)
EOF
